  "coque.accueil.canal_x": {"fr": "Publie fils et réponses via l'API v2.", "en": "Posts threads and replies via API v2."},
  "coque.accueil.canal_youtube": {"fr": "Envoie les Shorts sur votre chaîne via OAuth.", "en": "OAuth uploads Shorts to your channel."},
