  "coque.accueil.generateurs_texte": {"fr": "Les badges reflètent le contenu de backend/.env. Seul fal.ai est requis. Pour les plans marketing, vous pouvez utiliser Anthropic (cloud) OU un modèle Ollama local : avec Ollama, rien ne quitte votre machine. Modifiez backend/.env et redémarrez pour appliquer.", "en": "The badges reflect what's in backend/.env. Only fal.ai is required. For marketing plans you can use Anthropic (cloud) OR a local Ollama model — nothing leaves your machine with Ollama. Edit backend/.env and restart to apply."},
  "coque.accueil.generateurs_titre": {"fr": "Branchez vos fournisseurs de génération.", "en": "Plug in your generation providers."},
  "coque.accueil.local_1": {"fr": "Tout tourne en local. Les clés d'API vont dans ", "en": "Everything runs locally. API keys go in "},
  "coque.accueil.local_2": {"fr": ". Vos rendus ne quittent pas votre machine avant qu'un post du Planificateur ne parte.", "en": ". Your renders never leave your machine until a Scheduler post fires."},
  "coque.accueil.ollama": {"fr": "Ollama (LLM local)", "en": "Ollama (local LLM)"},
