  "montage.barre.annuler_clips": {"fr": " « Annuler » (Ctrl+Z) retire d'un coup ce qui vient d'être posé : l'historique de cet écran mémorise tout l'état du montage.", "en": " “Undo” (Ctrl+Z) removes what was just placed in one go: this screen's history records the whole editing state."},
  "montage.barre.annuler_panneau": {"fr": " Ouvrir ou fermer ce panneau n'entre pas dans l'historique et ne déplace pas la tête de lecture.", "en": " Opening or closing this panel does not go into the history and does not move the playhead."},
  "montage.barre.annuler_piste": {"fr": " « Annuler » (Ctrl+Z) retire la piste : l'historique de cet écran mémorise les pistes depuis le 21/09/2026. Le « × » de l'en-tête de la piste la retire aussi.", "en": " “Undo” (Ctrl+Z) removes the track: this screen's history has recorded tracks since 2026-09-21. The “×” in the track header removes it too."},
  "montage.barre.annuler_projet": {"fr": " Ouvrir la liste n'entre pas dans l'historique et ne déplace pas la tête de lecture. Ouvrir un PROJET, en revanche, remplace le montage affiché, VIDE l'historique et ramène la tête à zéro : la liste demande confirmation avant.", "en": " Opening the list does not go into the history and does not move the playhead. Opening a PROJECT, however, replaces the displayed edit, CLEARS the history and brings the playhead back to zero: the list asks for confirmation first."},
  "montage.barre.annuler_style": {"fr": " « Annuler » (Ctrl+Z) revient dessus : ce réglage entre dans l'historique (une entrée par rafale de 600 ms).", "en": " “Undo” (Ctrl+Z) reverts it: this setting goes into the history (one entry per 600 ms burst)."},
  "montage.barre.btn_couleur": {"fr": "couleur", "en": "color"},
  "montage.barre.btn_incrust": {"fr": "incrust.", "en": "overlay"},
