  "montage.extraire.aucun_plan": {"fr": "Aucun plan à source n'est sélectionné : rien à extraire.", "en": "No clip with a source is selected: nothing to extract."},
  "montage.extraire.bouton": {"fr": "Extraire le son → {piste}", "en": "Extract sound → {piste}"},
  "montage.extraire.bouton_aide": {"fr": "Poser sur {piste} (piste de dialogue) un clip « {clip} » : même source, mêmes bornes, même point d'entrée. Le rendu n'emporte JAMAIS l'audio embarqué d'un plan vidéo — sans ce clip, ce plan sort muet. Refusé si la source n'a pas de piste audio ou si ce son est déjà sur {piste} à cette plage. « Annuler » (Ctrl+Z) le retire.", "en": "Places a clip “{clip}” on {piste} (dialogue track): same source, same bounds, same in point. The render NEVER carries a video clip's embedded audio — without this clip, the clip plays muted. Refused if the source has no audio track or if this sound is already on {piste} at this range. “Undo” (Ctrl+Z) removes it."},
  "montage.extraire.bouton_sans_dialogue": {"fr": "Extraire le son (aucune piste de dialogue)", "en": "Extract sound (no dialogue track)"},
  "montage.extraire.bouton_sans_piste": {"fr": "Ce projet n'a pas de piste de dialogue : ajoutez une piste avec « + piste audio » pour pouvoir extraire le son de ce plan.", "en": "This project has no dialogue track: add a track with “+ audio track” to be able to extract this clip's sound."},
  "montage.extraire.doublon": {"fr": "Le son de « {nom} » est déjà sur {piste} (même source, même plage) : rien n'a été ajouté.", "en": "The sound of “{nom}” is already on {piste} (same source, same range): nothing was added."},
  "montage.extraire.image": {"fr": "« {nom} » est une image : elle n'a pas de son à extraire.", "en": "“{nom}” is an image: it has no sound to extract."},
