  "montage.extraire.non_sondable": {"fr": "« {nom} » n'a pas pu être sondé (aucune durée mesurable : fichier vide ou illisible) : rien à extraire. Vérifiez le fichier, ou remplacez la source.", "en": "“{nom}” could not be probed (no measurable duration: empty or unreadable file): nothing to extract. Check the file, or replace the source."},
  "montage.extraire.note_incrust": {"fr": " Posé sur {piste} (incrustation) : le son de ce plan n'a PAS été extrait — sélectionnez-le puis « Extraire le son{cible} » dans l'inspecteur.", "en": " Placed on {piste} (overlay): this clip's sound was NOT extracted — select it, then “Extract sound{cible}” in the inspector."},
  "montage.extraire.plan_absent": {"fr": "« {nom} » n'est plus dans la timeline : rien n'a été posé.", "en": "“{nom}” is no longer in the timeline: nothing was placed."},
  "montage.extraire.pose": {"fr": "Son de « {nom} » extrait sur {piste} : « {clip} », {duree}, mêmes bornes et même source que le plan. « Annuler » (Ctrl+Z) le retire.", "en": "Sound of “{nom}” extracted to {piste}: “{clip}”, {duree}, same bounds and same source as the clip. “Undo” (Ctrl+Z) removes it."},
  "montage.extraire.sans_piste": {"fr": "Ce projet n'a pas de piste de dialogue : le son de « {nom} » n'a pas été extrait. Ajoutez une piste avec « + piste audio », puis recommencez.", "en": "This project has no dialogue track: the sound of “{nom}” was not extracted. Add a track with “+ audio track”, then try again."},
  "montage.extraire.sonde_echec": {"fr": "La sonde audio de « {nom} » n'a pas abouti ({raison}) : rien n'a été posé. Réessayez dans un instant.", "en": "The audio probe of “{nom}” failed ({raison}): nothing was placed. Try again in a moment."},
