  "montage.pistes.v1_base_aide": {"fr": "V1 est la piste de base du montage — elle ne se retire pas", "en": "V1 is the base track of the edit — it cannot be removed"},
  "montage.pistes.v1_base_note": {"fr": "V1 est la piste de base du montage : elle ne peut pas être retirée.", "en": "V1 is the base track of the edit: it cannot be removed."},
  "montage.plage.aucune": {"fr": "Aucune plage : I pose l'entrée, U la sortie.", "en": "No range: I sets the in, U the out."},
