  "montage.projets.dupliquer_aide": {"fr": "Dupliquer « {nom} » — une copie indépendante, sous un nom suffixé « (copie) ». Rien d'autre ne bouge.", "en": "Duplicate “{nom}” — an independent copy, under a name suffixed “(copie)”. Nothing else moves."},
  "montage.projets.enregistre_sous": {"fr": "Montage enregistré sous « {nom} ». Les modifications suivantes y vont toutes seules, sans un geste de plus.", "en": "Edit saved as “{nom}”. Further changes go there on their own, with no extra step."},
  "montage.projets.enregistrer_sous": {"fr": "enregistrer sous…", "en": "save as…"},
  "montage.projets.enregistrer_sous_aide": {"fr": "Enregistrer le montage AFFICHÉ comme un nouveau projet. Rien n'est écrasé : c'est un fichier de plus, et c'est lui qui recevra les modifications suivantes. Champ vide : le nom courant est repris.", "en": "Save the DISPLAYED edit as a new project. Nothing is overwritten: it is one more file, and it is the one that will receive further changes. Empty field: the current name is reused."},
  "montage.projets.illisible": {"fr": "Projet illisible — comparaison impossible", "en": "Unreadable project — cannot compare"},
  "montage.projets.liste_occupee": {"fr": "Liste des projets occupée — ouvrez « {nom} » depuis ☰ › Projets.", "en": "Project list busy — open “{nom}” from ☰ › Projects."},
  "montage.projets.montage_vide": {"fr": "montage vide", "en": "empty edit"},
