  "montage.selecteur.note_audio": {"fr": "Posé à la tête de lecture ({t}). A1 = dialogue, A2 = musique (ducking auto), A3 = SFX.", "en": "Placed at the playhead ({t}). A1 = dialogue, A2 = music (auto ducking), A3 = SFX."},
  "montage.selecteur.note_video": {"fr": "Posé à la tête de lecture ({t}) — ou déposez directement sur une bande ou le viewport. Les PNG gardent leur transparence.", "en": "Placed at the playhead ({t}) — or drop straight onto a lane or the viewport. PNGs keep their transparency."},
  "montage.selecteur.regle_absente": {"fr": "Règle d'extensions vidéo indisponible (GET /api/montage/media-rules) — la liste « Rendus vidéo » n'est PAS filtrée : elle peut proposer des planches de sprites ou des maillages 3D, que le rendu refusera.", "en": "Video extension rule unavailable (GET /api/montage/media-rules) — the “Video renders” list is NOT filtered: it may offer sprite sheets or 3D meshes, which the render will refuse."},
  "montage.selecteur.remplacer_note": {"fr": "Le prochain élément choisi REMPLACERA la source de ce plan (piste {piste}) au lieu d'être posé : ses bornes, ses effets, sa transition et son mixage restent en place. Un glisser-déposer compte aussi comme un choix — la piste et l'instant du dépôt sont alors ignorés. Fermez ce panneau pour annuler.", "en": "The next item you pick will REPLACE this clip's source (track {piste}) instead of being placed: its bounds, effects, transition and mix stay in place. A drag-and-drop also counts as a pick — the drop track and time are then ignored. Close this panel to cancel."},
  "montage.selecteur.remplacer_titre": {"fr": "Remplacer la source de « {nom} »", "en": "Replace the source of “{nom}”"},
  "montage.selecteur.rendus_video": {"fr": "Rendus vidéo", "en": "Video renders"},
  "montage.solo.aide": {"fr": "Solo d'écoute : les autres pistes sont coupées en lecture directe — le rendu, lui, ne change jamais.", "en": "Listening solo: the other tracks are muted in live playback — the render itself never changes."},
  "montage.solo.badge_aide": {"fr": "Solo d'écoute ({pistes}) — lecture directe seulement, le rendu n'est jamais modifié", "en": "Listening solo ({pistes}) — live playback only, the render is never changed"},
  "montage.solo.sans_effet_apercu": {"fr": " · sans effet sur l'aperçu 480p (mix composite)", "en": " · no effect on the 480p preview (composite mix)"},
  "montage.sons.insertion_demo": {"fr": "Insertion : disponible sur un projet réel — générez ou importez d'abord une vidéo, la timeline se remplira.", "en": "Insertion: available on a real project — generate or import a video first, the timeline will fill up."},
