  "montage.source_plan.duree_inconnue": {"fr": "Durée de la nouvelle source inconnue : les bornes du plan n'ont pas pu être vérifiées — contrôlez sa fin.", "en": "New source duration unknown: the clip bounds could not be checked — check its end."},
  "montage.source_plan.entree_zero": {"fr": "Point d'entrée ramené à 0 : la nouvelle source ({d} s) ne va pas assez loin pour l'ancien. Le plan garde sa durée, il ne montre plus le même morceau.", "en": "In point reset to 0: the new source ({d} s) does not reach far enough for the old one. The clip keeps its duration, but no longer shows the same portion."},
  "montage.source_plan.raccourci": {"fr": "La nouvelle source ne dure que {d} s : le plan a été raccourci de {de} s à {a} s, et la timeline garde un trou derrière lui{suite}", "en": "The new source only lasts {d} s: the clip was shortened from {de} s to {a} s, and the timeline keeps a gap behind it{suite}"},
  "montage.source_plan.remplacee": {"fr": "Source de « {ancien} » remplacée par « {nouveau} ». Bornes, effets, transition et mixage conservés.{suite} Annuler restaure les clips et le mixage — pas la durée du projet ni les pistes ; « Revenir à la version précédente » rend aussi l'ancienne source.", "en": "Source of “{ancien}” replaced with “{nouveau}”. Bounds, effects, transition and mix kept.{suite} Undo restores the clips and the mix — not the project duration or the tracks; “Revert to previous version” also restores the old source."},
  "montage.source_plan.remplacer": {"fr": "Remplacer la source…", "en": "Replace source…"},
  "montage.source_plan.remplacer_aide": {"fr": "Échanger le fichier source de ce plan sans toucher au montage : ses bornes sur la timeline, ses effets, sa transition et son mixage restent en place. La Bibliothèque s'ouvre ; le clip que vous y choisirez remplacera la source au lieu d'être ajouté.", "en": "Swap this clip's source file without touching the edit: its timeline bounds, effects, transition and mix stay in place. The Library opens; the clip you pick there will replace the source instead of being added."},
  "montage.source_plan.remplacer_aria": {"fr": "Remplacer la source de {nom}", "en": "Replace source of {nom}"},
  "montage.source_plan.rendue": {"fr": "Source précédente rendue : « {nom} », avec son point d'entrée et sa fin d'alors.{suite}", "en": "Previous source restored: “{nom}”, with its in point and end from back then.{suite}"},
  "montage.source_plan.revenir": {"fr": "Revenir à la version précédente", "en": "Revert to previous version"},
  "montage.source_plan.revenir_aide.plusieurs": {"fr": "Rendre à ce plan sa source précédente, « {nom} », avec le point d'entrée et la fin qu'il avait alors. {n} versions en mémoire (10 au plus, les plus anciennes tombent).", "en": "Give this clip back its previous source, “{nom}”, with the in point and end it had then. {n} versions in memory (10 max, the oldest drop off)."},
  "montage.source_plan.revenir_aide.un": {"fr": "Rendre à ce plan sa source précédente, « {nom} », avec le point d'entrée et la fin qu'il avait alors. {n} version en mémoire (10 au plus, les plus anciennes tombent).", "en": "Give this clip back its previous source, “{nom}”, with the in point and end it had then. {n} version in memory (10 max, the oldest drop off)."},
