  "montage.texte.aucun_remplissage": {"fr": "Aucun mot de remplissage repéré dans cette narration", "en": "No filler word found in this narration"},
  "montage.texte.aucune_hesitation_plusieurs": {"fr": "Aucune hésitation. Les {n} mots soulignés sont des mots PLEINS : à couper à la sélection, en les lisant.", "en": "No hesitation. The {n} underlined words are FULL words: cut them with the selection, reading them."},
  "montage.texte.aucune_hesitation_un": {"fr": "Aucune hésitation. Les {n} mot souligné sont des mots PLEINS : à couper à la sélection, en les lisant.", "en": "No hesitation. The {n} underlined word is a FULL word: cut it with the selection, reading it."},
  "montage.texte.couper": {"fr": "couper la sélection", "en": "cut the selection"},
  "montage.texte.couper_aide": {"fr": "Couper de {a} s à {b} s sur toutes les pistes non verrouillées : ce qui suit remonte. Annuler défait la coupe entièrement. La durée du projet ne bouge pas : la fin de la timeline est maintenant vide, raccourcissez-la si vous voulez.", "en": "Cut from {a} s to {b} s on all unlocked tracks: what follows moves up. Undo reverts the cut entirely. The project duration does not change: the end of the timeline is now empty, shorten it if you like."},
  "montage.texte.coupes_plusieurs": {"fr": "{n} coupes — {s} s retirés. Annuler défait la coupe entièrement. La durée du projet ne bouge pas : la fin de la timeline est maintenant vide, raccourcissez-la si vous voulez.", "en": "{n} cuts — {s} s removed. Undo reverts the whole cut. The project length does not change: the end of the timeline is now empty, shorten it if you like."},
  "montage.texte.coupes_un": {"fr": "{n} coupe — {s} s retirés. Annuler défait la coupe entièrement. La durée du projet ne bouge pas : la fin de la timeline est maintenant vide, raccourcissez-la si vous voulez.", "en": "{n} cut — {s} s removed. Undo reverts the whole cut. The project length does not change: the end of the timeline is now empty, shorten it if you like."},
  "montage.texte.echec_requete": {"fr": "échec de la requête", "en": "request failed"},
  "montage.texte.hesitation": {"fr": "Hésitation — ", "en": "Hesitation — "},
  "montage.texte.mot_aide": {"fr": " · cliquer, Maj+clic ou glisser pour étendre la sélection", "en": " · click, Shift+click or drag to extend the selection"},
  "montage.texte.mot_cite": {"fr": "« {m} »", "en": "“{m}”"},
  "montage.texte.n_mots": {"fr": "{n} mots", "en": "{n} words"},
  "montage.texte.pas_de_receveur": {"fr": "Texte : rien pour recevoir la coupe.", "en": "Text: nothing to receive the cut."},
  "montage.texte.pistes_verrouillees": {"fr": " Pistes verrouillées ({pistes}) : leurs clips n'ont pas bougé.", "en": " Locked tracks ({pistes}): their clips did not move."},
  "montage.texte.retirer_aide_plusieurs": {"fr": "Retirer {mots} — {n} plages, de la fin vers le début pour que les précédentes ne se décalent pas. Seules les HÉSITATIONS partent ainsi ; les mots béquille soulignés se coupent à la sélection, un par un. Annuler défait la coupe entièrement. La durée du projet ne bouge pas : la fin de la timeline est maintenant vide, raccourcissez-la si vous voulez.", "en": "Remove {mots} — {n} ranges, from the end to the start so the earlier ones do not shift. Only HESITATIONS go this way; the underlined filler words are cut with the selection, one by one. Undo reverts the cut entirely. The project duration does not change: the end of the timeline is now empty, shorten it if you like."},
  "montage.texte.retirer_aide_un": {"fr": "Retirer {mots} — {n} plage, de la fin vers le début pour que les précédentes ne se décalent pas. Seules les HÉSITATIONS partent ainsi ; les mots béquille soulignés se coupent à la sélection, un par un. Annuler défait la coupe entièrement. La durée du projet ne bouge pas : la fin de la timeline est maintenant vide, raccourcissez-la si vous voulez.", "en": "Remove {mots} — {n} range, from the end to the start so the earlier ones do not shift. Only HESITATIONS go this way; the underlined filler words are cut with the selection, one by one. Undo reverts the cut entirely. The project duration does not change: the end of the timeline is now empty, shorten it if you like."},
  "montage.texte.retirer_euh": {"fr": "retirer les {n} « euh »", "en": "remove the {n} “uh”"},
  "montage.texte.rien_a_couper": {"fr": "Rien à couper : la sélection est vide.", "en": "Nothing to cut: the selection is empty."},
  "montage.texte.sans_temps": {"fr": "sans temps", "en": "no timing"},
  "montage.texte.selectionner_aide": {"fr": "Sélectionnez des mots (clic, Maj+clic, ou clic-glissé du premier au dernier)", "en": "Select words (click, Shift+click, or click-drag from the first to the last)"},
  "montage.texte.tic": {"fr": "Mot béquille (mot plein : à couper à la main, jamais en bloc) — ", "en": "Filler word (a full word: cut it by hand, never in bulk) — "},
  "montage.texte.titre": {"fr": "Texte", "en": "Text"},
  "montage.timeline.allongee_clip": {"fr": "Timeline allongée à {t} : « {nom} » dépasse la fin du projet, et n'a PAS été rogné pour autant. « Annuler » le ramène en place, et rend aussi la durée d'avant.", "en": "Timeline extended to {t}: “{nom}” goes past the end of the project, and was NOT trimmed for all that. “Undo” puts it back in place, and restores the previous duration too."},
  "montage.timeline.allongee_geste": {"fr": "Timeline allongée de {a} à {b} : le geste dépassait la fin du projet, et rien n'a été rogné. « Annuler » rend les clips, et rend aussi la durée d'avant.", "en": "Timeline extended from {a} to {b}: the gesture went past the end of the project, and nothing was trimmed. “Undo” restores the clips, and the previous duration too."},
