  "subs.cov.restent": {"fr": "{n} restent à traiter", "en": "{n} still to handle"},
  "subs.cov.retirees_plusieurs": {"fr": "RETIRÉES du total, muets à la livraison.", "en": "REMOVED from the total, silent on delivery."},
  "subs.cov.retirees_un": {"fr": "RETIRÉES du total, muet à la livraison.", "en": "REMOVED from the total, silent on delivery."},
  "subs.cov.revoquer": {"fr": "révoquer", "en": "revoke"},
  "subs.cov.revoquer_title": {"fr": "Remet ces plans dans le total : il remonte de {dur} s, le pourcentage redescend et ces plans redeviennent à sous-titrer. Le fichier livré ne change pas non plus dans ce sens.", "en": "Puts these clips back into the total: it goes up by {dur} s, the percentage goes down and these clips need subtitles again. The delivered file doesn't change in this direction either."},
