  "subs.karaoke.surligner": {"fr": "Surligner les mots prononcés", "en": "Highlight spoken words"},
  "subs.karaoke.surligner_aide": {"fr": "Chaque mot bascule à son tour et le reste jusqu'à la fin de la réplique — c'est ce que grave l'ASS, et l'aperçu le montre pareil", "en": "Each word switches in turn and stays that way until the end of the line — that is what ASS burns in, and the preview shows the same"},
  "subs.karaoke.timings_aide": {"fr": "Sans timings par mot venus de la transcription, la répartition est proportionnelle au nombre de caractères — chaque segment le dit.", "en": "Without per-word timings from the transcription, the split is proportional to the number of characters — each segment says so."},
  "subs.karaoke.titre": {"fr": "Karaoké", "en": "Karaoke"},
