  "subs.langue.ar": {"fr": "arabe", "en": "Arabic"},
  "subs.langue.auto": {"fr": "détection par le moteur", "en": "engine detection"},
  "subs.langue.contre": {"fr": "Le texte de la piste est en {langue} ({hits} mots reconnus sur {total}, contre {second_hits} en {second}), et ce panneau annonce « {choisie} » à chaque bouton qui dépense.", "en": "The track text is in {langue} ({hits} words recognized out of {total}, versus {second_hits} in {second}), and this panel announces “{choisie}” on every button that spends."},
  "subs.langue.de": {"fr": "allemand", "en": "German"},
  "subs.langue.detectee": {"fr": "Langue détectée d'après {ou} : {langue} ({hits} mots reconnus sur {total}). Le sélecteur reste maître.", "en": "Language detected from {ou}: {langue} ({hits} words recognized out of {total}). The selector stays in charge."},
  "subs.langue.en": {"fr": "anglais", "en": "English"},
  "subs.langue.es": {"fr": "espagnol", "en": "Spanish"},
  "subs.langue.flou": {"fr": "Langue indécise sur {ou} — {raison}. Rien n'a été choisi à votre place : le panneau reste sur « {langue} ».", "en": "Language undecided on {ou} — {raison}. Nothing was chosen for you: the panel stays on “{langue}”."},
  "subs.langue.fr": {"fr": "français", "en": "French"},
  "subs.langue.hi": {"fr": "hindi", "en": "Hindi"},
  "subs.langue.it": {"fr": "italien", "en": "Italian"},
