  "subs.langue.ko": {"fr": "coréen", "en": "Korean"},
  "subs.langue.nl": {"fr": "néerlandais", "en": "Dutch"},
  "subs.langue.ok": {"fr": "Langue lue sur {ou} : {langue}, {hits} mots reconnus sur {total}.", "en": "Language read from {ou}: {langue}, {hits} words recognized out of {total}."},
  "subs.langue.ok_aide": {"fr": "La langue lue sur le contenu est d'accord avec le sélecteur : {langue} ({hits} mots-outils reconnus sur {total} mots examinés). Rien à arbitrer.", "en": "The language read from the content agrees with the selector: {langue} ({hits} function words recognized out of {total} words examined). Nothing to settle."},
  "subs.langue.ok_auto_aide": {"fr": "Sous « auto » le moteur détecte lui-même la langue ; lue sur le contenu : {langue} ({hits} mots-outils reconnus sur {total} mots examinés). Rien à arbitrer.", "en": "Under “auto” the engine detects the language itself; read from the content: {langue} ({hits} function words recognized out of {total} words examined). Nothing to settle."},
  "subs.langue.passer": {"fr": "passer en {langue}", "en": "switch to {langue}"},
  "subs.langue.passer_aide": {"fr": "Règle le sélecteur sur « {langue} » — donc aussi la langue annoncée au moteur, le découpage en mots et le calage sur les silences. N'écrit RIEN dans la piste : aucune réplique n'est traduite ni retouchée.", "en": "Sets the selector to “{langue}” — and so also the language announced to the engine, the word splitting and the alignment on silences. Writes NOTHING to the track: no line is translated or edited."},
  "subs.langue.pl": {"fr": "polonais", "en": "Polish"},
  "subs.langue.pt": {"fr": "portugais", "en": "Portuguese"},
  "subs.langue.reglee": {"fr": "Langue réglée sur {langue} — aucune réplique n'a été touchée.", "en": "Language set to {langue} — no line was touched."},
  "subs.langue.ru": {"fr": "russe", "en": "Russian"},
  "subs.langue.tr": {"fr": "turc", "en": "Turkish"},
  "subs.langue.uk": {"fr": "ukrainien", "en": "Ukrainian"},
  "subs.langue.vide": {"fr": "Aucun texte à analyser : « {langue} » est le réglage, pas une lecture.", "en": "No text to analyze: “{langue}” is the setting, not a reading."},
  "subs.langue.zh": {"fr": "chinois", "en": "Chinese"},
  "subs.ligne.caler_ici": {"fr": "Caler la tête de lecture ici ({debut} → {fin}, {duree} s, {cps} car./s)", "en": "Move the playhead here ({debut} → {fin}, {duree} s, {cps} chars/s)"},
