  "subs.ligne.mots_repartis": {"fr": "mots répartis", "en": "words spread"},
  "subs.ligne.mots_repartis_title": {"fr": "Aucun timing par mot : la répartition du karaoké est proportionnelle au nombre de caractères.", "en": "No per-word timing: the karaoke is spread in proportion to the number of characters."},
