  "subs.neutre.couper_fond_effet": {"fr": "Le fond disparaît et le contour de {px} px se met à agir.", "en": "The background disappears and the {px} px outline takes effect."},
  "subs.neutre.sans_effet": {"fr": "sans effet", "en": "no effect"},
  "subs.norme.cadence": {"fr": "Cadence de référence", "en": "Reference frame rate"},
  "subs.norme.cadence_title": {"fr": "Cadence servant à traduire l'écart en images. Elle ne change aucun seuil : elle change la façon de le LIRE.", "en": "Frame rate used to convert the gap into frames. It changes no threshold: it changes how you READ it."},
  "subs.norme.duree_max": {"fr": "Durée max", "en": "Max duration"},
  "subs.norme.duree_max_aide": {"fr": "Au-delà, le sous-titre traîne à l'écran et on le relit.", "en": "Above this, the subtitle lingers on screen and gets read twice."},
  "subs.norme.duree_min": {"fr": "Durée min", "en": "Min duration"},
  "subs.norme.duree_min_aide": {"fr": "En deçà, l'œil n'a pas le temps de se poser sur la réplique.", "en": "Below this, the eye has no time to settle on the line."},
  "subs.norme.ebu": {"fr": "revenir à l'EBU", "en": "back to EBU"},
  "subs.norme.ebu_title": {"fr": "Revenir à la norme de diffusion française (EBU) : {cps} c/s, {min} – {max} s, écart {gap} ms.", "en": "Go back to the French broadcast standard (EBU): {cps} c/s, {min} – {max} s, gap {gap} ms."},
  "subs.norme.ecart": {"fr": "Écart min", "en": "Min gap"},
  "subs.norme.ecart_aide": {"fr": "Silence minimal entre deux répliques : en dessous, le changement se voit comme un clignotement.", "en": "Minimum silence between two lines: below it, the change looks like a flicker."},
