  "subs.norme.fps": {"fr": "{f} i/s", "en": "{f} fps"},
  "subs.norme.images_title": {"fr": "Le même écart, compté en images à la cadence choisie — c'est l'unité dans laquelle une coupe se juge.", "en": "The same gap, counted in frames at the chosen frame rate — the unit in which a cut is judged."},
  "subs.norme.norme": {"fr": "Norme", "en": "Standard"},
  "subs.norme.norme_aria": {"fr": "Norme de sous-titrage", "en": "Subtitling standard"},
  "subs.norme.norme_title": {"fr": "Trois normes courantes. Toute valeur changée à la main bascule sur « personnalisé » : le panneau n'affichera jamais le nom d'une norme qu'il n'applique pas.", "en": "Three common standards. Any value changed by hand switches to “custom”: the panel will never show the name of a standard it doesn't apply."},
  "subs.norme.note": {"fr": "Ces seuils partent avec le contrôle : le moteur mesure avec eux. Changer une valeur remarque la piste entière.", "en": "These thresholds are sent with the check: the engine measures with them. Changing a value re-flags the whole track."},
  "subs.norme.perso": {"fr": "personnalisé", "en": "custom"},
  "subs.norme.regler": {"fr": "régler ▸", "en": "adjust ▸"},
  "subs.norme.regler_title": {"fr": "Régler les seuils — norme du diffuseur, ou valeurs à la main", "en": "Set the thresholds — broadcaster standard, or values by hand"},
  "subs.norme.replier": {"fr": "replier ▾", "en": "collapse ▾"},
  "subs.norme.replier_title": {"fr": "Replier le réglage des seuils", "en": "Collapse the threshold settings"},
  "subs.norme.titre": {"fr": "Seuils", "en": "Thresholds"},
  "subs.norme.titre_title": {"fr": "Ces quatre seuils décident de chaque pastille de la liste et de chaque pastille de la piste S1. Ils partent AVEC le contrôle : le moteur mesure avec eux, pas avec les siens.", "en": "These four thresholds decide every badge in the list and every badge on track S1. They are sent WITH the check: the engine measures with them, not with its own."},
  "subs.norme.val": {"fr": "{cps} c/s · {min}–{max} s · écart {gap} ms = {img} images", "en": "{cps} c/s · {min}–{max} s · gap {gap} ms = {img} frames"},
  "subs.norme.val_title": {"fr": "Au-delà de {cps} caractères par seconde la lecture décroche ; sous {min} s l'œil n'a pas le temps de se poser ; au-delà de {max} s le sous-titre traîne ; sous {gap} ms le changement se voit comme un clignotement.", "en": "Above {cps} characters per second, reading drops off; under {min} s the eye has no time to settle; above {max} s the subtitle lingers; under {gap} ms the change looks like a flicker."},
  "subs.norme.vitesse": {"fr": "Vitesse max", "en": "Max speed"},
  "subs.norme.vitesse_aide": {"fr": "Caractères par seconde au-delà desquels la lecture décroche. EBU : 20. Netflix français : 17. Réseaux sociaux : 25.", "en": "Characters per second above which reading drops off. EBU: 20. French Netflix: 17. Social networks: 25."},
  "subs.normes.ebu": {"fr": "Diffusion FR / EBU", "en": "FR broadcast / EBU"},
