  "subs.plan.corriger": {"fr": "Corriger", "en": "Fix"},
  "subs.plan.couvert_title": {"fr": "{couvert} s de répliques visibles et non vides sur les {dur} s du plan = {pct} %", "en": "{couvert} s of visible, non-empty lines over the clip's {dur} s = {pct}%"},
  "subs.plan.decale_suivants": {"fr": "Décale les {n} sous-titres suivants de {ms}. Leur texte ne suivra plus la voix — à ne faire que si le montage suit.", "en": "Shifts the {n} following subtitles by {ms}. Their text will no longer follow the voice — only do this if the edit follows."},
  "subs.plan.decaler_sortirait": {"fr": "Décaler les suivants sortirait le dernier sous-titre de la vidéo ({trop} de trop).", "en": "Shifting the following ones would push the last subtitle past the end of the video ({trop} over)."},
  "subs.plan.decouper_effet": {"fr": "Le segment devient {n} sous-titres ({durs}), coupés sur les mots avec {ms} de respiration entre eux. Les voisins ne bougent pas.", "en": "The segment becomes {n} subtitles ({durs}), cut on words with {ms} of breathing room between them. The neighbors do not move."},
  "subs.plan.decouper_en": {"fr": "Découper en {n} sous-titres", "en": "Split into {n} subtitles"},
  "subs.plan.decouper_rien": {"fr": "Le texte tient en un seul bloc de {n} caractères : rien à découper.", "en": "The text fits in a single block of {n} characters: nothing to split."},
  "subs.plan.ecrire_apres": {"fr": "Pose une réplique VIDE au début du plan et y amène la tête de lecture. Une réplique SANS TEXTE ne couvre rien — ni au rendu, ni dans ce calcul : la couverture reste à {pct} % et le plan reste signalé jusqu'à ce que le texte soit tapé.", "en": "Places an EMPTY line at the start of the clip and moves the playhead there. A line WITHOUT TEXT covers nothing — neither in the render nor in this calculation: coverage stays at {pct}% and the clip stays flagged until the text is typed."},
  "subs.plan.ecrire_ici": {"fr": "Écrire ici", "en": "Write here"},
  "subs.plan.ecrire_math": {"fr": "écrire ici : une réplique VIDE ne couvre rien → {couvert} ÷ {attendu} = {pct} % inchangé.", "en": "write here: an EMPTY line covers nothing → {couvert} ÷ {attendu} = {pct}% unchanged."},
  "subs.plan.et": {"fr": " et ", "en": " and "},
  "subs.plan.etirer_a": {"fr": "Étirer à {s} s", "en": "Stretch to {s} s"},
  "subs.plan.etirer_assez": {"fr": "Le segment dure déjà assez longtemps.", "en": "The segment is already long enough."},
  "subs.plan.etirer_decaler": {"fr": "Étirer à {s} s en décalant la suite", "en": "Stretch to {s} s by shifting the rest"},
  "subs.plan.finit_avec_video": {"fr": "le segment finit déjà avec la vidéo", "en": "the segment already ends with the video"},
  "subs.plan.frontiere_large": {"fr": "La frontière est déjà assez large.", "en": "The boundary is already wide enough."},
  "subs.plan.fusionner": {"fr": "Fusionner les deux", "en": "Merge both"},
  "subs.plan.fusionner_effet": {"fr": "Le {a} et le {b} deviennent un seul sous-titre de {s} s. Le texte est mis bout à bout, le calage par mot est refait.", "en": "{a} and {b} become a single {s} s subtitle. The text is joined end to end, the word timing is redone."},
  "subs.plan.il_faudrait": {"fr": "Il faudrait {s} s : le voisin ne laisse pas plus. Le problème sera réduit, pas effacé.", "en": "It would need {s} s: the neighbor leaves no more room. The problem will be reduced, not removed."},
  "subs.plan.il_restera": {"fr": "Il restera : ", "en": "Will remain: "},
  "subs.plan.ne_reduirait": {"fr": "ne réduirait rien — il créerait {liste} en échange. Prenez l'autre geste.", "en": "would reduce nothing — it would create {liste} in exchange. Use the other action."},
  "subs.plan.numero": {"fr": "n°{n}", "en": "#{n}"},
  "subs.plan.pas_de_voisin": {"fr": "Pas de voisin avant ce segment.", "en": "No neighbor before this segment."},
  "subs.plan.plus_aucun_ecart": {"fr": "Après : plus aucun écart.", "en": "After: no discrepancy left."},
  "subs.plan.prend": {"fr": "Le segment prend {bits}. Aucun voisin ne bouge.", "en": "The segment takes {bits}. No neighbor moves."},
  "subs.plan.reglage_cesse": {"fr": "Le réglage « {champ} » cessera d'agir ({court}).", "en": "The “{champ}” setting will stop taking effect ({court})."},
  "subs.plan.replier_deja": {"fr": "Le texte est déjà replié au mieux pour {n} caractères par ligne.", "en": "The text is already wrapped as well as possible for {n} characters per line."},
  "subs.plan.replier_effet": {"fr": "Le texte est replié à {n} caractères par ligne ({longs}). Le début, la fin et le calage par mot ne bougent pas.", "en": "The text is wrapped at {n} characters per line ({longs}). The start, the end and the word timing do not move."},
  "subs.plan.replier_en": {"fr": "Replier en {n} lignes", "en": "Wrap into {n} lines"},
  "subs.plan.replier_trop": {"fr": "Le texte fait {n} lignes à {c} caractères : il ne tient pas en {max}.", "en": "The text takes {n} lines at {c} characters: it does not fit in {max}."},
  "subs.plan.sans_parole": {"fr": "sans parole", "en": "no speech"},
  "subs.plan.separer_de": {"fr": "Séparer de {ms}", "en": "Separate by {ms}"},
  "subs.plan.separer_effet": {"fr": "Le {a} perd {ta} à la fin, le {b} {tb} au début. Écart final {gap}, et les deux restent au-dessus de {min} s.", "en": "{a} loses {ta} at the end, {b} {tb} at the start. Final gap {gap}, and both stay above {min} s."},
  "subs.plan.separer_impossible": {"fr": "Impossible sans passer sous {min} s : le {a} dure {da} s, le {b} {db} s, et il manque {ms}. Fusionnez-les, ou raccourcissez un texte.", "en": "Impossible without going under {min} s: {a} lasts {da} s, {b} {db} s, and {ms} is missing. Merge them, or shorten a text."},
  "subs.plan.silence_apres": {"fr": "{ms} de silence après", "en": "{ms} of silence after"},
  "subs.plan.silence_avant": {"fr": "{ms} de silence avant", "en": "{ms} of silence before"},
  "subs.plan.transcrire": {"fr": "Transcrire ce plan", "en": "Transcribe this clip"},
  "subs.plan.transcrire_apres": {"fr": "Écrit des répliques entre {debut} et {fin}, en remplaçant ce que la piste y avait déjà ; les autres plans ne bougent pas. Sans parole détectée, rien n'est écrit et le plan reste signalé.", "en": "Writes lines between {debut} and {fin}, replacing what the track already had there; the other clips don't move. If no speech is detected, nothing is written and the clip stays flagged."},
  "subs.plan.vide_posee": {"fr": "Réplique vide posée à {tc} sur le plan n°{n} — tapez le texte.", "en": "Empty line placed at {tc} on clip #{n} — type the text."},
