  "subs.rangee.gratuit_aide": {"fr": "Le texte de la narration est déjà écrit : le moteur le cale sur les silences réels du son. Rien n'est envoyé, rien n'est deviné, aucun nom propre n'est écorché.", "en": "The narration text is already written: the engine aligns it on the actual silences of the audio. Nothing is sent, nothing is guessed, no proper name is mangled."},
  "subs.rangee.langue": {"fr": "langue", "en": "language"},
  "subs.rangee.langue_aide": {"fr": "Langue annoncée au moteur : elle change le découpage en mots et le calage sur les silences. Elle est écrite sur chaque bouton qui lance une transcription.", "en": "Language announced to the engine: it changes the word splitting and the alignment on silences. It is written on every button that starts a transcription."},
  "subs.rangee.langue_aria": {"fr": "Langue de la transcription", "en": "Transcription language"},
