  "subs.rangee.nouvelle_piste": {"fr": "nouvelle piste", "en": "new track"},
  "subs.rangee.nouvelle_piste_aide": {"fr": "Coché : la traduction naît dans une nouvelle piste de sous-titres S2, S3… (S1 reste intacte ; la piste gravée au rendu se choisit par clic droit sur sa tête). Décoché : S1 est réécrite.", "en": "Checked: the translation goes into a new subtitle track S2, S3… (S1 stays intact; the track burned in at render is chosen by right-clicking its header). Unchecked: S1 is rewritten."},
  "subs.rangee.nouvelle_piste_aria": {"fr": "Traduire dans une nouvelle piste", "en": "Translate into a new track"},
  "subs.rangee.payant_aide": {"fr": "Écrire, découper, caler, styler, le karaoké et l'export .SRT/.VTT/.TXT ne coûtent rien et marchent hors ligne : seule la transcription d'un son sans texte est payante.", "en": "Writing, splitting, aligning, styling, karaoke and .SRT/.VTT/.TXT export cost nothing and work offline: only transcribing audio without text is paid."},
